examples.template:
Box(
    modifier = Modifier.onPreviewKeyEvent { event ->
        val shortcut = event.type == KeyEventType.KeyDown && event.isCtrlPressed && event.key == Key.K
        if (shortcut) open = true
        shortcut
    },
) {
    MonarchButton(text = {{trigger}}, onClick = { open = true })
}
if (opened.isNotEmpty()) MonarchText(text = "Opened: $opened")
if (open) {
    MonarchDialog(
        onDismissRequest = {
            open = false
            query = ""
        },
        title = null,
        paneTitle = "Jump to",
    ) {
        Column(modifier = Modifier.fillMaxWidth()) {
            MonarchSearchBar(
                query = query,
                onQueryChange = { query = it },
                onSearch = {},
                modifier = Modifier.fillMaxWidth(),
                placeholder = {{trigger}},
            )
            val text = query.trim()
            val groups = if (text.isEmpty()) {
                // Recent places while nothing is typed, then every channel and person, as on the web.
                listOf(MonarchSearchResultGroup("Recent", "recent", recent.map { MonarchSearchResult(it.second, it.first, snippet = snippets[it.first], icon = { MonarchIcon(if (it.third == {{groups.1.label}}) SampleIcons.Users else SampleIcons.Inbox, contentDescription = null) }) })) +
                    destinations.groupBy { it.third }
                        .map { (group, list) ->
                            MonarchSearchResultGroup(group, group, list.map { MonarchSearchResult(it.second, it.first, snippet = snippets[it.first], icon = { MonarchIcon(if (it.third == {{groups.1.label}}) SampleIcons.Users else SampleIcons.Inbox, contentDescription = null) }) })
                        }
            } else {
                destinations.filter { it.second.contains(text, ignoreCase = true) }
                    .groupBy { it.third }
                    .map { (group, list) ->
                        MonarchSearchResultGroup(group, group, list.map { MonarchSearchResult(it.second, it.first, snippet = snippets[it.first], icon = { MonarchIcon(if (it.third == {{groups.1.label}}) SampleIcons.Users else SampleIcons.Inbox, contentDescription = null) }) })
                    } +
                    // The search-everywhere fallback under the instant matches.
                    MonarchSearchResultGroup("Search", "search", listOf(MonarchSearchResult("Search for “$text”", "search")))
            }
            MonarchSearchResults(
                groups = groups,
                onSelect = { result, _ ->
                    opened = result.title
                    open = false
                    query = ""
                },
                modifier = Modifier.heightIn(max = 520.dp),
                query = query,
            )
        }
    }
}

